import React from "react";
import { useCart } from "./CartContext";
import { useNavigate } from "react-router-dom";  // Import useNavigate

const Cart = () => {
    const { cart, addToCart, removeFromCart, updateQuantity, totalItems, totalPrice, placeOrder } = useCart();
    const navigate = useNavigate();

    const handleCheckout = () => {
        // Thực hiện thanh toán và lưu đơn hàng
        const orderDetails = {
            info: "Thông tin giao hàng",
            name: "Tên người nhận",
            address: "Địa chỉ",
            city: "Tỉnh",
            date: new Date().toLocaleDateString(),
        };

        placeOrder(orderDetails); // Gọi hàm đặt hàng

        alert("Đặt hàng thành công!");
        navigate("/donhang");  // Chuyển hướng đến trang đơn hàng
    };

    return (
        <div className="container my-5">
            <div className="row">
                {/* Sản phẩm trong giỏ hàng - bên trái */}
                <div className="col-md-8">
                    <h2 className="mb-4">Giỏ Hàng</h2>
                    <div className="cart-items">
                        {cart.length === 0 ? (
                            <p className="text-center">Giỏ hàng của bạn trống.</p>
                        ) : (
                            cart.map((product) => (
                                <div key={product.id} className="cart-item d-flex align-items-center mb-4 p-4 border rounded shadow-sm">
                                    <img
                                        src={product.image}
                                        alt={product.name}
                                        className="product-image rounded"
                                        style={{ width: "120px", height: "120px", objectFit: "cover" }}
                                    />
                                    <div className="cart-item-details mx-3 w-75">
                                        <h5 className="mb-2">{product.name}</h5>
                                        <p className="mb-3 text-muted">{product.description}</p>
                                        <div className="d-flex align-items-center mb-3">
                                            <button
                                                className="btn btn-outline-secondary mx-2"
                                                onClick={() => updateQuantity(product.id, "decrease")}
                                            >
                                                -
                                            </button>
                                            <span className="mx-2">{product.quantity}</span>
                                            <button
                                                className="btn btn-outline-secondary mx-2"
                                                onClick={() => updateQuantity(product.id, "increase")}
                                            >
                                                +
                                            </button>
                                        </div>
                                        <p className="price mb-2">
                                            <strong>Giá: {product.price} VND</strong>
                                        </p>
                                    </div>
                                    <button
                                        className="btn btn-danger"
                                        onClick={() => removeFromCart(product.id)}
                                    >
                                        <i className="bi bi-trash"></i> Xóa
                                    </button>
                                </div>
                            ))
                        )}
                    </div>
                </div>

                {/* Phần thanh toán - bên phải */}
                <div className="col-md-4">
                    <h3 className="mb-4">Thông Tin Thanh Toán</h3>
                    <div className="cart-summary p-4 border rounded shadow-sm">
                        <p><strong>Tổng Số Lượng:</strong> {totalItems}</p>
                        <p><strong>Tổng Tiền:</strong> {totalPrice} VND</p>
                        <button className="btn btn-success w-100" onClick={handleCheckout}>
                            Thanh Toán
                        </button>
                    </div>
                </div>
            </div>

            {/* Sản phẩm gợi ý - dưới cùng */}
            <div className="suggested-products mt-5">
                <h4 className="text-center mb-4">Sản Phẩm Gợi Ý</h4>
                <div className="row">
                    {/* Các sản phẩm gợi ý */}
                    {[...Array(4)].map((_, index) => (
                        <div className="col-md-3 mb-4" key={index}>
                            <div className="card shadow-sm">
                                <img src="product-image.jpg" alt="Product" className="card-img-top" />
                                <div className="card-body text-center">
                                    <h5 className="card-title">Sản phẩm {index + 1}</h5>
                                    <p className="card-text">Giá: {100000 * (index + 1)} VND</p>
                                    <button
                                        className="btn btn-primary"
                                        onClick={() => addToCart({
                                            id: index + 1,
                                            name: `Sản phẩm ${index + 1}`,
                                            price: 100000 * (index + 1),
                                            image: 'product-image.jpg',
                                            description: `Mô tả sản phẩm ${index + 1}`
                                        })}
                                    >
                                        Thêm vào giỏ
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default Cart;
